import sys, dis
from reflex.utils.format import length_of_largest_common_substring

TARGET = length_of_largest_common_substring
instr_map = {ins.offset: ins for ins in dis.get_instructions(TARGET)}
TRACK = {'str1','str2','dp','max_length','i','j'}
pairs = set()
defs = {}

def tracer(frame, event, arg):
    if event == 'call' and frame.f_code is TARGET.__code__:
        frame.f_trace_opcodes = True
        defs['str1'] = TARGET.__code__.co_firstlineno
        defs['str2'] = TARGET.__code__.co_firstlineno
        return tracer
    if frame.f_code is not TARGET.__code__:
        return tracer
    if event == 'opcode':
        ins = instr_map.get(frame.f_lasti)
        if not ins:
            return tracer
        if ins.opname in ('LOAD_FAST','LOAD_DEREF') and ins.argval in TRACK:
            d = defs.get(ins.argval)
            if d is not None:
                pairs.add((ins.argval, d, frame.f_lineno))
        elif ins.opname in ('STORE_FAST','STORE_DEREF') and ins.argval in TRACK:
            defs[ins.argval] = frame.f_lineno
    return tracer

sys.settrace(tracer)
res = TARGET('abracadabra-trace','cadabra-trial')
sys.settrace(None)
print('result',res)
for p in sorted(pairs):
    print(p)
PY

